    "Use this computer as the server": { ru: "Использовать этот компьютер как сервер", zh: "将此电脑用作服务器", hi: "इस कंप्यूटर को सर्वर बनाएं", es: "Usar esta computadora como servidor", ar: "استخدام هذا الجهاز كخادم", fr: "Utiliser cet ordinateur comme serveur", pt: "Usar este computador como servidor", de: "Diesen Computer als Server verwenden", it: "Usa questo computer come server", pl: "Użyj tego komputera jako serwera" },
    "Server health check": { ru: "Диагностика сервера", zh: "服务器健康检查", hi: "सर्वर स्वास्थ्य जाँच", es: "Comprobación del servidor", ar: "فحص حالة الخادم", fr: "Vérification du serveur", pt: "Verificação do servidor", de: "Server-Prüfung", it: "Controllo del server", pl: "Kontrola serwera" },
    "Your Gonka wallet (Account Key)": { ru: "Ваш кошелёк Gonka (Account Key)", zh: "您的Gonka钱包（账户密钥）", hi: "आपका Gonka वॉलेट (Account Key)", es: "Tu billetera Gonka (Account Key)", ar: "محفظة Gonka الخاصة بك (مفتاح الحساب)", fr: "Votre portefeuille Gonka (Account Key)", pt: "Sua carteira Gonka (Account Key)", de: "Ihre Gonka-Wallet (Account Key)", it: "Il tuo portafoglio Gonka (Account Key)", pl: "Twój portfel Gonka (Account Key)" },
