    "Write down your recovery phrase": { ru: "Запишите фразу восстановления", zh: "写下您的恢复短语", hi: "अपनी रिकवरी फ्रेज़ लिखें", es: "Anota tu frase de recuperación", ar: "اكتب عبارة الاسترداد", fr: "Notez votre phrase de récupération", pt: "Anote sua frase de recuperação", de: "Wiederherstellungsphrase notieren", it: "Annota la frase di recupero", pl: "Zapisz frazę odzyskiwania" },
    "How will the network reach your node?": { ru: "Как сеть будет связываться с вашим узлом?", zh: "网络如何访问您的节点？", hi: "नेटवर्क आपके नोड तक कैसे पहुँचेगा?", es: "¿Cómo llegará la red a tu nodo?", ar: "كيف ستصل الشبكة إلى عقدتك؟", fr: "Comment le réseau atteindra-t-il votre nœud ?", pt: "Como a rede alcançará seu nó?", de: "Wie erreicht das Netzwerk Ihren Node?", it: "Come raggiungerà la rete il tuo nodo?", pl: "Jak sieć dotrze do twojego węzła?" },
    "Pick your model configuration": { ru: "Выберите конфигурацию модели", zh: "选择您的模型配置", hi: "अपनी मॉडल कॉन्फ़िगरेशन चुनें", es: "Elige tu configuración de modelo", ar: "اختر إعداد النموذج", fr: "Choisissez votre configuration de modèle", pt: "Escolha sua configuração de modelo", de: "Modellkonfiguration wählen", it: "Scegli la configurazione del modello", pl: "Wybierz konfigurację modelu" },
