    "Verify your node": { ru: "Проверьте свой узел", zh: "验证您的节点", hi: "अपने नोड की पुष्टि करें", es: "Verifica tu nodo", ar: "تحقق من عقدتك", fr: "Vérifiez votre nœud", pt: "Verifique seu nó", de: "Node überprüfen", it: "Verifica il tuo nodo", pl: "Zweryfikuj węzeł" },
    "Collateral — unlock full rewards": { ru: "Залог — откройте полные награды", zh: "抵押——解锁全部奖励", hi: "संपार्श्विक — पूर्ण पुरस्कार खोलें", es: "Colateral: desbloquea todas las recompensas", ar: "الضمان — كامل المكافآت", fr: "Collatéral — récompenses complètes", pt: "Colateral — recompensas completas", de: "Collateral — volle Belohnungen", it: "Collaterale — ricompense complete", pl: "Zabezpieczenie — pełne nagrody" },
