    "Send": { ru: "Отправить", zh: "发送", hi: "भेजें", es: "Enviar", ar: "إرسال", fr: "Envoyer", pt: "Enviar", de: "Senden", it: "Invia", pl: "Wyślij" },
    "Enter how much GNK to send.": { ru: "Укажите, сколько GNK отправить.", zh: "请输入要发送多少 GNK。", hi: "बताएँ कि कितने GNK भेजने हैं।", es: "Indica cuánto GNK enviar.", ar: "حدّد كمية GNK المراد إرسالها.", fr: "Indiquez combien de GNK envoyer.", pt: "Informe quanto GNK enviar.", de: "Geben Sie an, wie viel GNK gesendet werden soll.", it: "Indica quanti GNK inviare.", pl: "Podaj, ile GNK wysłać." },
    "Send {amt} GNK to {to}? This can't be undone.": { ru: "Отправить {amt} GNK на {to}? Отменить это будет нельзя.", zh: "确认向 {to} 发送 {amt} GNK？此操作无法撤销。", hi: "{to} को {amt} GNK भेजें? इसे वापस नहीं लिया जा सकता।", es: "¿Enviar {amt} GNK a {to}? Esto no se puede deshacer.", ar: "إرسال {amt} GNK إلى {to}؟ لا يمكن التراجع عن ذلك.", fr: "Envoyer {amt} GNK à {to} ? C'est irréversible.", pt: "Enviar {amt} GNK para {to}? Isso não pode ser desfeito.", de: "{amt} GNK an {to} senden? Das lässt sich nicht rückgängig machen.", it: "Inviare {amt} GNK a {to}? Non si può annullare.", pl: "Wysłać {amt} GNK na {to}? Tego nie da się cofnąć." },
    "Signing on this computer and sending…": { ru: "Подписываем на этом компьютере и отправляем…", zh: "正在本机签名并发送…", hi: "इसी कंप्यूटर पर हस्ताक्षर करके भेज रहे हैं…", es: "Firmando en este ordenador y enviando…", ar: "جارٍ التوقيع على هذا الجهاز والإرسال…", fr: "Signature sur cet ordinateur et envoi…", pt: "Assinando neste computador e enviando…", de: "Wird auf diesem Computer signiert und gesendet…", it: "Firma su questo computer e invio…", pl: "Podpisywanie na tym komputerze i wysyłanie…" },
    "Sent. Transaction:": { ru: "Отправлено. Транзакция:", zh: "已发送。交易：", hi: "भेज दिया गया। ट्रांज़ैक्शन:", es: "Enviado. Transacción:", ar: "تم الإرسال. المعاملة:", fr: "Envoyé. Transaction :", pt: "Enviado. Transação:", de: "Gesendet. Transaktion:", it: "Inviato. Transazione:", pl: "Wysłano. Transakcja:" },
