    "{tokens} tokens": { ru: "{tokens} токенов", zh: "{tokens} 个 token", hi: "{tokens} टोकन", es: "{tokens} tokens", ar: "{tokens} رمز", fr: "{tokens} tokens", pt: "{tokens} tokens", de: "{tokens} Token", it: "{tokens} token", pl: "{tokens} tokenów" },
    "{tokens} tokens · {cost}": { ru: "{tokens} токенов · {cost}", zh: "{tokens} 个 token · {cost}", hi: "{tokens} टोकन · {cost}", es: "{tokens} tokens · {cost}", ar: "{tokens} رمز · {cost}", fr: "{tokens} tokens · {cost}", pt: "{tokens} tokens · {cost}", de: "{tokens} Token · {cost}", it: "{tokens} token · {cost}", pl: "{tokens} tokenów · {cost}" },
    "No model is available from this service right now.": { ru: "Сейчас у этого сервиса нет доступной модели.", zh: "该服务目前没有可用的模型。", hi: "इस सेवा से अभी कोई मॉडल उपलब्ध नहीं है।", es: "Ahora mismo este servicio no ofrece ningún modelo.", ar: "لا يوجد نموذج متاح من هذه الخدمة الآن.", fr: "Aucun modèle n'est disponible auprès de ce service pour le moment.", pt: "Nenhum modelo está disponível neste serviço agora.", de: "Von diesem Dienst ist gerade kein Modell verfügbar.", it: "Da questo servizio non è disponibile nessun modello al momento.", pl: "Ta usługa nie udostępnia teraz żadnego modelu." },
    "Stop": { ru: "Остановить", zh: "停止", hi: "रोकें", es: "Detener", ar: "إيقاف", fr: "Arrêter", pt: "Parar", de: "Stopp", it: "Ferma", pl: "Zatrzymaj" },
    "Use the AI models running on the Gonka network, through your own account with a service that connects to it.": { ru: "Пользуйтесь моделями ИИ, работающими в сети Gonka, через собственный аккаунт у сервиса, который с ней соединяет.", zh: "通过你在某个接入服务上的账户，使用运行在 Gonka 网络上的 AI 模型。", hi: "Gonka नेटवर्क पर चल रहे AI मॉडल इस्तेमाल करें — उससे जोड़ने वाली किसी सेवा में अपने ख़ुद के खाते के ज़रिये।", es: "Usa los modelos de IA que corren en la red Gonka, a través de tu propia cuenta en un servicio que conecta con ella.", ar: "استخدم نماذج الذكاء الاصطناعي العاملة على شبكة Gonka عبر حسابك الخاص لدى خدمة تتصل بها.", fr: "Utilisez les modèles d'IA qui tournent sur le réseau Gonka, via votre propre compte chez un service qui s'y connecte.", pt: "Use os modelos de IA que rodam na rede Gonka, pela sua própria conta em um serviço que se conecta a ela.", de: "Nutzen Sie die KI-Modelle im Gonka-Netzwerk über Ihr eigenes Konto bei einem Dienst, der es anbindet.", it: "Usa i modelli di IA che girano sulla rete Gonka, tramite il tuo account presso un servizio che vi si collega.", pl: "Korzystaj z modeli AI działających w sieci Gonka przez własne konto w usłudze, która się z nią łączy." },
    "Approved by governance, but the network is paying nobody to run them this epoch:": { ru: "Одобрены управлением, но в этой эпохе сеть никому не платит за их запуск:", zh: "已通过治理批准，但本轮 epoch 网络不为运行它们付费：", hi: "गवर्नेंस से मंज़ूर, लेकिन इस epoch में नेटवर्क इन्हें चलाने का किसी को भुगतान नहीं कर रहा:", es: "Aprobados por la gobernanza, pero esta época la red no paga a nadie por ejecutarlos:", ar: "معتمدة من الحوكمة، لكن الشبكة لا تدفع لأحد مقابل تشغيلها في هذه الحقبة:", fr: "Approuvés par la gouvernance, mais ce cycle le réseau ne paie personne pour les faire tourner :", pt: "Aprovados pela governança, mas nesta época a rede não paga ninguém para rodá-los:", de: "Von der Governance genehmigt, aber in dieser Epoche zahlt das Netzwerk niemandem fürs Betreiben:", it: "Approvati dalla governance, ma in questa epoca la rete non paga nessuno per eseguirli:", pl: "Zatwierdzone przez zarządzanie, ale w tej epoce sieć nikomu za nie nie płaci:" },
    "Hardware rented for these earns nothing right now, so they are left out of the tables above. They come back on their own if the network starts paying for them again.": { ru: "Железо, арендованное под них, сейчас ничего не заработает, поэтому в таблицах выше их нет. Они вернутся сами, если сеть снова начнёт за них платить.", zh: "为它们租用的硬件现在赚不到任何收益，所以上面的表格里不列出。如果网络重新为它们付费，它们会自动回到表中。", hi: "इनके लिए किराए पर लिया गया हार्डवेयर अभी कुछ नहीं कमाएगा, इसलिए ऊपर की तालिकाओं में ये नहीं हैं। अगर नेटवर्क फिर से इनके लिए भुगतान करने लगा, तो ये अपने आप लौट आएँगे।", es: "El hardware alquilado para estos no gana nada ahora mismo, así que quedan fuera de las tablas de arriba. Vuelven solos si la red empieza a pagar por ellos otra vez.", ar: "العتاد المستأجر لأجلها لا يكسب شيئًا الآن، لذا استُبعدت من الجداول أعلاه. وستعود من تلقاء نفسها إذا عادت الشبكة إلى الدفع مقابلها.", fr: "Le matériel loué pour ceux-ci ne rapporte rien en ce moment, ils sont donc exclus des tableaux ci-dessus. Ils y reviennent d'eux-mêmes si le réseau se remet à les payer.", pt: "O hardware alugado para estes não ganha nada agora, por isso ficam fora das tabelas acima. Eles voltam sozinhos se a rede voltar a pagar por eles.", de: "Für diese gemietete Hardware verdient derzeit nichts, deshalb fehlen sie in den Tabellen oben. Sie kommen von selbst zurück, wenn das Netzwerk wieder für sie zahlt.", it: "L'hardware noleggiato per questi non guadagna nulla al momento, quindi restano fuori dalle tabelle qui sopra. Tornano da soli se la rete ricomincia a pagarli.", pl: "Sprzęt wynajęty pod nie nic teraz nie zarobi, więc nie ma ich w tabelach powyżej. Wrócą same, jeśli sieć znów zacznie za nie płacić." },

