    "{name}, a community project": { ru: "{name} — проект сообщества", zh: "{name}，社区项目", hi: "{name}, एक कम्युनिटी प्रोजेक्ट", es: "{name}, un proyecto de la comunidad", ar: "{name}، مشروع مجتمعي", fr: "{name}, un projet communautaire", pt: "{name}, um projeto da comunidade", de: "{name}, ein Community-Projekt", it: "{name}, un progetto della comunità", pl: "{name}, projekt społeczności" },
    "{name}, the team behind Gonka": { ru: "{name} — команда, которая делает Gonka", zh: "{name}，Gonka 背后的团队", hi: "{name}, Gonka बनाने वाली टीम", es: "{name}, el equipo que está detrás de Gonka", ar: "{name}، الفريق الذي يقف وراء Gonka", fr: "{name}, l'équipe derrière Gonka", pt: "{name}, a equipe por trás da Gonka", de: "{name}, das Team hinter Gonka", it: "{name}, il team dietro Gonka", pl: "{name}, zespół stojący za Gonką" },
    "Workspaces: an assistant that writes documents, slides, spreadsheets and code": { ru: "Workspaces: помощник, который пишет документы, презентации, таблицы и код", zh: "Workspaces：能写文档、幻灯片、表格和代码的助手", hi: "Workspaces: एक सहायक जो दस्तावेज़, स्लाइड, स्प्रेडशीट और कोड लिखता है", es: "Workspaces: un asistente que escribe documentos, diapositivas, hojas de cálculo y código", ar: "Workspaces: مساعد يكتب المستندات والشرائح والجداول والشيفرة", fr: "Workspaces : un assistant qui rédige documents, diapositives, tableurs et code", pt: "Workspaces: um assistente que escreve documentos, slides, planilhas e código", de: "Workspaces: ein Assistent, der Dokumente, Folien, Tabellen und Code schreibt", it: "Workspaces: un assistente che scrive documenti, slide, fogli di calcolo e codice", pl: "Workspaces: asystent, który pisze dokumenty, slajdy, arkusze i kod" },
    "Can search the web and read PDFs": { ru: "Умеет искать в интернете и читать PDF", zh: "可以联网搜索并阅读 PDF", hi: "वेब पर खोज सकता है और PDF पढ़ सकता है", es: "Puede buscar en la web y leer PDF", ar: "يمكنه البحث في الويب وقراءة ملفات PDF", fr: "Peut chercher sur le web et lire des PDF", pt: "Pode pesquisar na web e ler PDFs", de: "Kann im Web suchen und PDFs lesen", it: "Può cercare sul web e leggere i PDF", pl: "Potrafi szukać w sieci i czytać PDF-y" },
    "Also works with Claude Code and other Anthropic tools": { ru: "Работает также с Claude Code и другими инструментами Anthropic", zh: "也可搭配 Claude Code 及其他 Anthropic 工具使用", hi: "Claude Code और दूसरे Anthropic टूल के साथ भी चलता है", es: "También funciona con Claude Code y otras herramientas de Anthropic", ar: "يعمل أيضًا مع Claude Code وأدوات Anthropic الأخرى", fr: "Fonctionne aussi avec Claude Code et les autres outils d'Anthropic", pt: "Também funciona com o Claude Code e outras ferramentas da Anthropic", de: "Funktioniert auch mit Claude Code und anderen Anthropic-Werkzeugen", it: "Funziona anche con Claude Code e altri strumenti di Anthropic", pl: "Działa też z Claude Code i innymi narzędziami Anthropic" },
    "No fee on GNK, 5% on USDT": { ru: "Без комиссии в GNK, 5% в USDT", zh: "用 GNK 免手续费，用 USDT 收 5%", hi: "GNK पर कोई शुल्क नहीं, USDT पर 5%", es: "Sin comisión en GNK, 5% en USDT", ar: "بدون رسوم على GNK، و5% على USDT", fr: "Sans frais en GNK, 5 % en USDT", pt: "Sem taxa em GNK, 5% em USDT", de: "Keine Gebühr bei GNK, 5 % bei USDT", it: "Nessuna commissione in GNK, 5% in USDT", pl: "Bez prowizji w GNK, 5% w USDT" },
    "Network price plus a 10% fee": { ru: "Цена сети плюс комиссия 10%", zh: "网络价格加 10% 手续费", hi: "नेटवर्क क़ीमत के ऊपर 10% शुल्क", es: "Precio de la red más una comisión del 10%", ar: "سعر الشبكة زائد رسوم 10%", fr: "Prix du réseau plus 10 % de frais", pt: "Preço da rede mais uma taxa de 10%", de: "Netzwerkpreis plus 10 % Gebühr", it: "Prezzo della rete più una commissione del 10%", pl: "Cena sieci plus 10% prowizji" },
    "Or monthly plans from $9": { ru: "Либо месячные тарифы от 9 $", zh: "或选择每月 9 美元起的套餐", hi: "या $9 से शुरू होने वाले मासिक प्लान", es: "O planes mensuales desde 9 $", ar: "أو باقات شهرية تبدأ من 9 دولارات", fr: "Ou des forfaits mensuels à partir de 9 $", pt: "Ou planos mensais a partir de 9 $", de: "Oder Monatstarife ab 9 $", it: "Oppure piani mensili da 9 $", pl: "Albo plany miesięczne od 9 $" },

    /* ---- Use Gonka ---- */
    "Connected": { ru: "Подключён", zh: "已连接", hi: "जुड़ा हुआ", es: "Conectado", ar: "متصل", fr: "Connecté", pt: "Conectado", de: "Verbunden", it: "Collegato", pl: "Połączono" },
    "Switch to {name}": { ru: "Перейти на {name}", zh: "切换到 {name}", hi: "{name} पर जाएँ", es: "Cambiar a {name}", ar: "التبديل إلى {name}", fr: "Passer à {name}", pt: "Mudar para {name}", de: "Zu {name} wechseln", it: "Passa a {name}", pl: "Przełącz na {name}" },
