    "{n} bytes": { ru: "{n} байт", zh: "{n} 字节", hi: "{n} बाइट", es: "{n} bytes", ar: "{n} بايت", fr: "{n} octets", pt: "{n} bytes", de: "{n} Bytes", it: "{n} byte", pl: "{n} bajtów" },
    "This creates a new file in your folder.": { ru: "Будет создан новый файл в вашей папке.", zh: "这会在你的文件夹里创建一个新文件。", hi: "इससे आपके फ़ोल्डर में एक नई फ़ाइल बनेगी।", es: "Esto crea un archivo nuevo en tu carpeta.", ar: "سيؤدي هذا إلى إنشاء ملف جديد في مجلدك.", fr: "Cela crée un nouveau fichier dans votre dossier.", pt: "Isso cria um arquivo novo na sua pasta.", de: "Das legt eine neue Datei in Ihrem Ordner an.", it: "Questo crea un nuovo file nella tua cartella.", pl: "To utworzy nowy plik w twoim folderze." },
    "This replaces a file that is already there.": { ru: "Будет заменён файл, который уже есть.", zh: "这会覆盖已经存在的文件。", hi: "इससे पहले से मौजूद फ़ाइल बदल जाएगी।", es: "Esto reemplaza un archivo que ya existe.", ar: "سيحل هذا محل ملف موجود بالفعل.", fr: "Cela remplace un fichier déjà présent.", pt: "Isso substitui um arquivo que já existe.", de: "Das ersetzt eine Datei, die schon da ist.", it: "Questo sostituisce un file già presente.", pl: "To zastąpi plik, który już tam jest." },
    "Write it": { ru: "Записать", zh: "写入", hi: "लिख दें", es: "Escribir", ar: "اكتبه", fr: "Écrire", pt: "Escrever", de: "Schreiben", it: "Scrivi", pl: "Zapisz" },
    "Skip this": { ru: "Пропустить", zh: "跳过", hi: "छोड़ दें", es: "Omitir", ar: "تخطّي", fr: "Passer", pt: "Pular", de: "Überspringen", it: "Salta", pl: "Pomiń" },
    "Stopped after {n} steps, so this doesn't run away on its own. Ask it to carry on if it should keep going.": { ru: "Остановлено после {n} шагов, чтобы это не работало само по себе без конца. Попросите продолжить, если нужно дальше.", zh: "已在 {n} 步后停下，以免它自己一直跑下去。需要继续的话，让它接着做。", hi: "{n} क़दम के बाद रोक दिया, ताकि यह अपने आप चलता न रहे। आगे बढ़ाना हो तो कहें कि जारी रखे।", es: "Parado tras {n} pasos, para que no siga solo indefinidamente. Pídele que continúe si debe seguir.", ar: "توقّف بعد {n} خطوات حتى لا يستمر من تلقاء نفسه. اطلب منه المتابعة إذا أردت.", fr: "Arrêté après {n} étapes, pour que cela ne parte pas tout seul. Demandez-lui de continuer si besoin.", pt: "Parou depois de {n} passos, para não seguir sozinho sem fim. Peça para continuar se for o caso.", de: "Nach {n} Schritten gestoppt, damit das nicht von allein weiterläuft. Bitten Sie es weiterzumachen, wenn es soll.", it: "Fermato dopo {n} passi, così non va avanti da solo all'infinito. Chiedigli di continuare se serve.", pl: "Zatrzymane po {n} krokach, żeby nie działało samo w nieskończoność. Poproś, żeby kontynuowało, jeśli trzeba." },
    "{name} Workspaces ↗": { ru: "Workspaces в {name} ↗", zh: "{name} 的 Workspaces ↗", hi: "{name} का Workspaces ↗", es: "Workspaces de {name} ↗", ar: "Workspaces لدى {name} ↗", fr: "Workspaces de {name} ↗", pt: "Workspaces da {name} ↗", de: "Workspaces bei {name} ↗", it: "Workspaces di {name} ↗", pl: "Workspaces w {name} ↗" },

