    "Look at the folder": { ru: "Посмотреть, что в папке", zh: "查看文件夹", hi: "फ़ोल्डर देखें", es: "Mirar la carpeta", ar: "استعراض المجلد", fr: "Regarder le dossier", pt: "Olhar a pasta", de: "Ordner ansehen", it: "Guarda la cartella", pl: "Zobacz folder" },

